"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { type InlineEditStatus, useInlineEdit, type InlineEditFailure, enter } from "./inline-edit-state";
import { cn } from "@/lib/utils";

export const buttonBase =
  "inline-flex h-9 shrink-0 items-center justify-center gap-1.5 rounded-md px-3 text-sm font-medium whitespace-nowrap outline-none focus-visible:ring-1 focus-visible:ring-ring aria-disabled:opacity-60";

export type ActionProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  children?: ReactNode | ((status: InlineEditStatus) => ReactNode);
};

/** Submits the draft. Stays focusable while pending so focus is not lost. */
export const InlineEditSave = forwardRef<HTMLButtonElement, ActionProps>(function InlineEditSave({ children, className, ...props }, ref) {
  const { status, conflict } = useInlineEdit();
  const unavailable = status === "pending" || conflict;
  const fallback = status === "pending" ? "Saving…" : status === "error" ? "Retry" : "Save";
  return (
    <button
      ref={ref}
      type="submit"
      aria-disabled={unavailable || undefined}
      aria-busy={status === "pending" || undefined}
      className={cn(buttonBase, "bg-primary text-primary-foreground hover:bg-primary/90", className)}
      {...props}
    >
      {typeof children === "function" ? children(status) : children ?? fallback}
    </button>
  );
});

export const InlineEditCancel = forwardRef<HTMLButtonElement, ActionProps>(function InlineEditCancel(
  { children, className, onClick, ...props },
  ref,
) {
  const { status, cancel } = useInlineEdit();
  return (
    <button
      ref={ref}
      type="button"
      aria-disabled={status === "pending" || undefined}
      className={cn(buttonBase, "hover:bg-accent hover:text-accent-foreground", className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) cancel();
      }}
      {...props}
    >
      {typeof children === "function" ? children(status) : children ?? "Cancel"}
    </button>
  );
});

export type InlineEditErrorProps = Omit<ComponentPropsWithoutRef<"p">, "children"> & {
  children?: ReactNode | ((failure: InlineEditFailure) => ReactNode);
};

/** Validation or save failure, linked to the input. Renders nothing otherwise. */
export const InlineEditError = forwardRef<HTMLParagraphElement, InlineEditErrorProps>(function InlineEditError(
  { children, className, ...props },
  ref,
) {
  const { variant, failure, errorId, animated } = useInlineEdit();
  if (!failure) return null;
  const retry = variant === "ghost" ? "Couldn’t save. Press Enter to try again." : "Couldn’t save. Try again or cancel.";
  const fallback = failure.type === "invalid" ? failure.message : retry;
  return (
    <p ref={ref} id={errorId} role="alert" className={cn("text-sm text-destructive", animated && enter, className)} {...props}>
      {typeof children === "function" ? children(failure) : children ?? fallback}
    </p>
  );
});

export type InlineEditConflictProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  children?: ReactNode | ((conflict: { latest: string; acceptLatest: () => void; keepDraft: () => void }) => ReactNode);
};

/** Shown when the value changes elsewhere during an unsaved edit. Saving waits for a choice. */
export const InlineEditConflict = forwardRef<HTMLDivElement, InlineEditConflictProps>(function InlineEditConflict(
  { children, className, ...props },
  ref,
) {
  const { conflict, value, animated, acceptLatest, keepDraft } = useInlineEdit();
  if (!conflict) return null;
  return (
    <div
      ref={ref}
      role="status"
      className={cn("flex flex-wrap items-center gap-x-3 gap-y-1 rounded-md bg-muted px-3 py-2 text-sm", animated && enter, className)}
      {...props}
    >
      {typeof children === "function" ? (
        children({ latest: value, acceptLatest, keepDraft })
      ) : children ?? (
        <>
          <span className="text-muted-foreground">
            Changed elsewhere to <span className="font-medium text-foreground">“{value}”</span>.
          </span>
          <button type="button" className="font-medium underline underline-offset-4" onClick={acceptLatest}>
            Use latest
          </button>
          <button type="button" className="font-medium underline underline-offset-4" onClick={keepDraft}>
            Keep mine
          </button>
        </>
      )}
    </div>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { useInlineEdit, mergeRefs, enter } from "./inline-edit-state";
import { cn } from "@/lib/utils";

export type InlineEditPreviewProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  /** Replace the displayed value. */
  children?: ReactNode | ((value: string) => ReactNode);
  /** Shown when the value is empty. */
  placeholder?: ReactNode;
};

/** The committed value as a button that starts editing. Hidden while editing. */
export const InlineEditPreview = forwardRef<HTMLButtonElement, InlineEditPreviewProps>(function InlineEditPreview(
  { children, placeholder, className, onClick, onBlur, ...props },
  ref,
) {
  const { variant, value, label, editing, disabled, animated, start, previewRef } = useInlineEdit();
  if (editing) return null;
  const content = typeof children === "function" ? children(value) : children ?? (value || <span className="text-muted-foreground">{placeholder}</span>);
  return (
    <button
      ref={mergeRefs(ref, previewRef)}
      type="button"
      disabled={disabled}
      className={cn(
        "inline-flex items-center text-left text-sm outline-none focus-visible:underline focus-visible:underline-offset-4 disabled:opacity-50",
        variant === "ghost"
          ? // Hovering shows a faint underline where the editing line will draw in; no box highlight.
            cn(
              // Keyboard focus shows the underline in the editing color instead of a ring, except when it returns after editing.
              "relative min-h-8 rounded-sm px-1 after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-px after:origin-left after:scale-x-0 after:bg-muted-foreground/50 hover:after:scale-x-100 focus-visible:no-underline not-data-returned:focus-visible:after:scale-x-100 not-data-returned:focus-visible:after:bg-ring",
              animated && "after:transition-transform after:duration-200 after:ease-out motion-reduce:after:transition-none",
            )
          : "min-h-9 rounded-md px-2 hover:bg-accent hover:text-accent-foreground",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) start();
      }}
      onBlur={(event) => {
        onBlur?.(event);
        event.currentTarget.removeAttribute("data-returned");
      }}
      {...props}
    >
      <span className="sr-only">{label}: </span>
      {content}
    </button>
  );
});

/** Wraps the input and actions while editing. Enter submits; Escape cancels. */
export const InlineEditEditor = forwardRef<HTMLFormElement, ComponentPropsWithoutRef<"form">>(function InlineEditEditor(
  { className, onSubmit, onKeyDown, ...props },
  ref,
) {
  const { variant, editing, animated, save, cancel } = useInlineEdit();
  if (!editing) return null;
  return (
    <form
      ref={ref}
      noValidate
      className={cn(
        "flex items-center gap-2",
        variant === "ghost"
          ? // The underline draws in from the left when editing starts, and pulses while saving.
            cn(
              "relative after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-px after:origin-left after:bg-ring in-data-[status=pending]:after:animate-pulse in-data-[invalid]:after:bg-destructive",
              animated && "after:transition-transform after:duration-300 after:ease-out after:starting:scale-x-0 motion-reduce:after:transition-none",
            )
          : animated && enter,
        className,
      )}
      onSubmit={(event) => {
        onSubmit?.(event);
        event.preventDefault();
        save();
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || event.key !== "Escape") return;
        event.preventDefault();
        cancel();
      }}
      {...props}
    />
  );
});

export const InlineEditInput = forwardRef<HTMLInputElement, Omit<ComponentPropsWithoutRef<"input">, "value" | "defaultValue">>(
  function InlineEditInput({ className, onChange, onKeyDown, ...props }, ref) {
    const { variant, label, draft, status, failure, errorId, inputRef, setDraft } = useInlineEdit();
    return (
      <input
        ref={mergeRefs(ref, inputRef)}
        aria-label={label}
        aria-invalid={failure?.type === "invalid" || undefined}
        aria-describedby={failure ? errorId : undefined}
        readOnly={status === "pending"}
        className={cn(
          "w-full min-w-0 bg-transparent text-sm outline-none",
          variant === "ghost"
            ? // Same box and padding as the ghost preview, so the text does not move when editing starts.
              "h-8 px-1"
            : "h-9 rounded-md border border-input px-3 shadow-xs focus-visible:border-ring aria-invalid:border-destructive aria-invalid:ring-destructive/20",
          className,
        )}
        {...props}
        value={draft}
        onChange={(event) => {
          onChange?.(event);
          if (!event.defaultPrevented) setDraft(event.target.value);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          // Enter confirms an input-method composition instead of submitting.
          if (event.key === "Enter" && (event.nativeEvent.isComposing || event.keyCode === 229)) event.preventDefault();
        }}
      />
    );
  },
);

"use client";

import { forwardRef, useState, useRef, useId, useEffect } from "react";
import { type InlineEditProps, type Session, type InlineEditStatus, type InlineEditFailure, type InlineEditContextValue, InlineEditContext, mergeRefs } from "./inline-edit-state";
import { cn } from "@/lib/utils";

export const InlineEdit = forwardRef<HTMLDivElement, InlineEditProps>(function InlineEdit(
  {
    value,
    onSave,
    label,
    validate,
    editing: editingProp,
    defaultEditing = false,
    onEditingChange,
    onCancel,
    disabled = false,
    motion = true,
    variant = "default",
    saveOnBlur = variant === "ghost",
    className,
    onBlur,
    ...props
  },
  ref,
) {
  const [uncontrolledEditing, setUncontrolledEditing] = useState(defaultEditing);
  const editing = editingProp ?? uncontrolledEditing;
  const [session, setSession] = useState<Session | null>(null);
  const [status, setStatus] = useState<InlineEditStatus>("idle");
  const [failure, setFailure] = useState<InlineEditFailure | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const previewRef = useRef<HTMLButtonElement | null>(null);
  const restoreFocus = useRef(false);
  const attempt = useRef(0);
  const errorId = useId();

  // Open, close and follow the committed value while editing.
  if (editing && !session) setSession({ draft: value, base: value });
  if (!editing && session) {
    setSession(null);
    setStatus("idle");
    setFailure(null);
  }
  // A new committed value replaces an untouched draft, or one that already matches it.
  if (session && value !== session.base && (session.draft === session.base || session.draft === value)) {
    setSession({ draft: value, base: value });
  }
  const conflict = !!session && value !== session.base;

  const wasEditing = useRef(editing);
  useEffect(() => {
    if (wasEditing.current === editing) return;
    wasEditing.current = editing;
    if (editing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    } else if (restoreFocus.current) {
      // Marked so the ghost variant shows no focus line when focus comes back after Enter or Escape.
      previewRef.current?.setAttribute("data-returned", "");
      previewRef.current?.focus();
    }
    restoreFocus.current = false;
  }, [editing]);

  // Ignore results that arrive after unmount.
  useEffect(() => () => void attempt.current++, []);

  const setEditing = (next: boolean) => {
    if (editingProp === undefined) setUncontrolledEditing(next);
    onEditingChange?.(next);
  };

  const close = () => {
    restoreFocus.current = !!rootRef.current?.contains(document.activeElement);
    setEditing(false);
  };

  const save = async () => {
    if (!session || status === "pending" || conflict) return;
    const { draft } = session;
    if (draft === value) return close();
    const message = validate?.(draft);
    if (message) {
      setFailure({ type: "invalid", message });
      inputRef.current?.focus();
      return;
    }
    const current = ++attempt.current;
    setStatus("pending");
    setFailure(null);
    try {
      await onSave(draft);
      if (attempt.current !== current) return;
      setStatus("idle");
      close();
    } catch (cause) {
      if (attempt.current !== current) return;
      setStatus("error");
      setFailure({ type: "save", cause });
    }
  };

  const cancel = () => {
    if (status === "pending") return;
    close();
    onCancel?.();
  };

  const context: InlineEditContextValue = {
    variant,
    value,
    label,
    draft: session?.draft ?? value,
    editing,
    disabled,
    animated: motion,
    status,
    failure,
    conflict,
    errorId,
    inputRef,
    previewRef,
    setDraft: (draft) => {
      setSession((current) => current && { ...current, draft });
      if (failure?.type === "invalid") setFailure(null);
    },
    start: () => !disabled && setEditing(true),
    cancel,
    save: () => void save(),
    // The conflict notice unmounts after a choice, so focus moves back to the input.
    acceptLatest: () => {
      setSession({ draft: value, base: value });
      inputRef.current?.focus();
    },
    keepDraft: () => {
      setSession((current) => current && { ...current, base: value });
      inputRef.current?.focus();
    },
  };

  return (
    <InlineEditContext.Provider value={context}>
      <div
        ref={mergeRefs(ref, rootRef)}
        data-editing={editing || undefined}
        data-status={status}
        data-invalid={failure?.type === "invalid" || undefined}
        data-conflict={conflict || undefined}
        data-disabled={disabled || undefined}
        data-variant={variant}
        className={cn("grid", variant === "ghost" ? "gap-1" : "gap-2", className)}
        onBlur={(event) => {
          onBlur?.(event);
          // Focus moving within the editor (for example to a conflict choice) is not leaving it.
          if (!saveOnBlur || !session || rootRef.current?.contains(event.relatedTarget as Node | null)) return;
          if (status === "pending" || conflict) return;
          if (session.draft === value || validate?.(session.draft)) return cancel();
          void save();
        }}
        {...props}
      />
    </InlineEditContext.Provider>
  );
});

"use client";

import { type MutableRefObject, createContext, useContext, type Ref, type ComponentPropsWithoutRef } from "react";

export type InlineEditStatus = "idle" | "pending" | "error";

/** Why the current draft was not saved. `cause` is whatever `onSave` threw. */
export type InlineEditFailure = { type: "invalid"; message: string } | { type: "save"; cause: unknown };

export type Session = { draft: string; base: string };

export type InlineEditContextValue = {
  variant: InlineEditVariant;
  value: string;
  label: string;
  draft: string;
  editing: boolean;
  disabled: boolean;
  animated: boolean;
  status: InlineEditStatus;
  failure: InlineEditFailure | null;
  /** The committed value changed elsewhere while this draft had unsaved edits. */
  conflict: boolean;
  errorId: string;
  inputRef: MutableRefObject<HTMLInputElement | null>;
  previewRef: MutableRefObject<HTMLButtonElement | null>;
  setDraft: (draft: string) => void;
  start: () => void;
  cancel: () => void;
  save: () => void;
  acceptLatest: () => void;
  keepDraft: () => void;
};

export const InlineEditContext = createContext<InlineEditContextValue | null>(null);

/** State and actions of the nearest InlineEdit, for building custom parts. */
export function useInlineEdit() {
  const context = useContext(InlineEditContext);
  if (!context) throw new Error("InlineEdit parts must be rendered inside <InlineEdit>.");
  return context;
}

export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<T | null>).current = node;
    }
  };
}

export const enter = "transition duration-200 ease-out starting:-translate-y-0.5 starting:opacity-0 motion-reduce:transition-none";

/**
 * "default" shows a bordered input with Save and Cancel. "ghost" edits on top of the text
 * itself: a line draws in under it, Enter saves, Escape cancels and leaving saves.
 */
export type InlineEditVariant = "default" | "ghost";

export type InlineEditProps = Omit<ComponentPropsWithoutRef<"div">, "onChange"> & {
  /** The committed value. The application owns it and updates it after a successful save. */
  value: string;
  /** Persist the draft. Return a promise to show pending; reject to keep the draft and offer retry. */
  onSave: (draft: string) => void | Promise<unknown>;
  /** Accessible name of the field, such as "Task name". */
  label: string;
  /** Return a message to reject the draft before saving. */
  validate?: (draft: string) => string | null | undefined;
  editing?: boolean;
  defaultEditing?: boolean;
  onEditingChange?: (editing: boolean) => void;
  onCancel?: () => void;
  disabled?: boolean;
  /** Entrance transitions for the editor and messages. Reduced motion is always honored. */
  motion?: boolean;
  variant?: InlineEditVariant;
  /**
   * Leaving the field saves a valid change and reverts an invalid one. Defaults to on for
   * the ghost variant, which has no buttons, and off otherwise.
   */
  saveOnBlur?: boolean;
};

"use client";

export { type InlineEditStatus, type InlineEditFailure, useInlineEdit, type InlineEditVariant, type InlineEditProps } from "./inline-edit-state";
export { InlineEdit } from "./inline-edit-root";
export { type InlineEditPreviewProps, InlineEditPreview, InlineEditEditor, InlineEditInput } from "./inline-edit-field";
export { InlineEditSave, InlineEditCancel, type InlineEditErrorProps, InlineEditError, type InlineEditConflictProps, InlineEditConflict } from "./inline-edit-feedback";
